import{c as a,Q as r,j as t,m as n}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Building Agent Harnesses for Scientific Curation from Multimodal Sources","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.21005","title":"Building Agent Harnesses for Scientific Curation from Multimodal Sources","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.21005,"authors":["Sheng Zhang","Qin Liu","Renqian Luo","Shufang Xie","Reuben Tan","Sean Hayes","Gregory Bryman","Wendong Ge","Roxy Zhang","Oluwaseun Egbelowo","Kelly Yee","Hoifung Poon"],"domains":["cs.AI","cs.CL"],"html":"https://arxiv.org/html/2606.21005v1","pdf_path":"pdfs/2606.21005.pdf","published_date":"2026-06-19T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-19-beaver-agent-harness-scientific-curation-2606-21005.md","filePath":"research/papers/2026-06-19-beaver-agent-harness-scientific-curation-2606-21005.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-06-19-beaver-agent-harness-scientific-curation-2606-21005.md"};function i(s,e,l,c,u,d){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="building-agent-harnesses-for-scientific-curation-from-multimodal-sources" tabindex="-1">Building Agent Harnesses for Scientific Curation from Multimodal Sources <a class="header-anchor" href="#building-agent-harnesses-for-scientific-curation-from-multimodal-sources" aria-label="Permalink to &quot;Building Agent Harnesses for Scientific Curation from Multimodal Sources&quot;">​</a></h1><p><strong>Authors</strong>: Sheng Zhang, Qin Liu, Renqian Luo, Shufang Xie, Reuben Tan, Sean Hayes, Gregory Bryman, Wendong Ge, Roxy Zhang, Oluwaseun Egbelowo, Kelly Yee, Hoifung Poon <strong>Published</strong>: June 19, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.21005" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.21005</a> · <a href="https://arxiv.org/html/2606.21005v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.21005 <strong>Categories</strong>: cs.AI, cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.21005" target="_blank" rel="noreferrer">research/papers/pdfs/2606.21005.pdf</a> (20 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Scientific discovery workflows often depend on structured curation from the literature. This is difficult for current agents because the key evidence is scattered across long text, dense tables, and figures, and the final records often require reasoning across multiple evidence fragments rather than copying a single span. We study scientific curation from multimodal sources and introduce Beaver, an agent harness that extracts structured information from scientific papers while preserving provenance to the supporting evidence. Beaver combines a frontier agent with multimodal evidence tooling, task scaffolding, and artifact-grounded autoresearch. These components turn curation into a staged, auditable workflow and enable an iterative evaluate–diagnose–revise loop, where persistent run artifacts expose stage-localized failures and guide harness updates. Experiments show that Beaver reaches 81.0 on Gold-Referenced Attribute Score (GRAS), an attribute-level measure of agreement with gold curated records, outperforming frontier agents by over 23 absolute points. Ablations show that task scaffolding, multimodal evidence tooling, and provenance traces each contribute meaningfully to performance, while attribute-level analysis shows the largest gains on high-value attributes that require cross-modal reasoning and normalization. These results show that, for scientific curation from papers with multimodal evidence, harness design is a central determinant of agent performance.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p><strong>Beaver</strong> = 從多模態科學文獻做結構化 curation 的 agent harness，核心主張「harness 設計是 agent 表現的中心決定因素」。組成：</p><ol><li><strong>Frontier agent + multimodal evidence tooling</strong> — 跨長文 / 密集表格 / 圖的證據抽取。</li><li><strong>Task scaffolding</strong> — 把 curation 變成 staged、可稽核 workflow。</li><li><strong>Artifact-grounded autoresearch</strong> — persistent run artifact 暴露 <strong>stage-localized failure</strong>，驅動 <strong>evaluate→diagnose→revise</strong> 迭代與 harness 更新。</li><li><strong>Provenance preservation</strong> — 最終記錄保留到支撐證據的溯源（非單 span 複製，而需跨片段推理）。</li></ol><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li><strong>GRAS 81.0</strong>（attribute-level 與 gold 記錄一致度），超 frontier agent <strong>+23 絕對分</strong>。</li><li>Ablation：task scaffolding / multimodal tooling / provenance trace 各自顯著貢獻。</li><li>最大增益落在「需跨模態推理 + 正規化」的高價值屬性。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未列明確 limitation；依賴 frontier agent + 多模態工具，成本與領域泛化待驗。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>The Loop 同構（最直接者之一）</strong>：<code>evaluate→diagnose→revise</code> + persistent artifact 暴露 stage-localized failure = <code>OBSERVE→IDENTIFY→...→RECORD</code> 的 trace 化；artifact-grounded 對應本 workspace 的 <code>claude-progress.json</code> / RECORD checkpoint。</li><li><strong>autoresearch skill 直接呼應</strong>：「artifact-grounded autoresearch」+ modify→verify→keep/discard，幾乎是 autoresearch:learn / research-hub 的學術版；可作該 skill 設計參考。</li><li><strong>provenance / 溯源</strong>：對應 research-hub 歸檔的引用紀律與 deep-research 的 cited synthesis。</li><li>⚠️ 「harness design 為中心決定因素」+ ablation 證據，是支持 harness-engineering 投資的有力外部佐證；列入 KNOWLEDGE-MAP 證據池。</li></ul>',17)])])}const f=a(o,[["render",i]]);export{h as __pageData,f as default};
